Modified version of adummyredis with eternal loop

{noformat}import { Config } from "./config/Config";
import Context from "@taxify/nodejs-common/lib/logger/Context";
import HttpServiceApp from "@taxify/nodejs-common/lib/httpService/HttpServiceApp";
import { AsyncSetup } from "@taxify/nodejs-common/lib/nodeSetup/NodeSetup";
import { RedisConnection } from "@taxify/nodejs-common/lib/async/redis/RedisConnection";
import Logger from "@taxify/nodejs-common/lib/logger/Logger";
import { DbConnection } from "@taxify/nodejs-common/lib/async/db/DbConnection";
import { InternalRequestClient } from "@taxify/nodejs-common/lib/router/internalRequest/InternalRequestClient";

const logger = new Logger("Bootstrap");

const retryFn = async (ctx: any, id: any) => {
    console.log('REDIS DEAD!!------------')
    id && clearInterval(id);
    await setupConnection(ctx);
}

const setupConnection = async (ctx: any) => {
    let id: any;
    try {
        const redis = await RedisConnection.createAndInit(ctx, "adummyredis");
        id = setInterval(async () => {
            try {
                const pong = await redis.ping(ctx, `${Date.now()} - pong`);
                logger.info(ctx, "redis ping", { pong: pong });
            } catch (error) {
                await retryFn(ctx, id)
            }


        }, 1000);
    } catch (error) {
        await retryFn(ctx, id)
    }
}

export default class Bootstrap extends AsyncSetup<Config> {
    public async setup(ctx: Context, app: HttpServiceApp) {
        DbConnection.disableTtl(); // delete this line to enable query fail on exhausted TTL and select query server-side timeout
        InternalRequestClient.disableTtl(); // delete this line to enable fail on exhausted TTL

        await setupConnection(ctx);
    }
}
